#!/usr/bin/env dotnet
#:property AllowUnsafeBlocks=true

Span<nint> span = stackalloc nint[4];
span[0] = 10;
span[1] = 20;
span[2] = 30;
span[3] = 40;

Console.WriteLine($"Span<nint> length: {span.Length}");
Console.WriteLine($"nint size: {nint.Size} bytes");
for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"  span[{i}] = {span[i]}");

Span<nuint> unsigned = stackalloc nuint[2];
unsigned[0] = 100;
unsigned[1] = 200;
Console.WriteLine($"\nSpan<nuint> length: {unsigned.Length}");
for (int i = 0; i < unsigned.Length; i++)
    Console.WriteLine($"  unsigned[{i}] = {unsigned[i]}");

